def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not orderings:
        return []

    while True:
        merged = False
        for i in range(len(orderings)):
            for j in range(len(orderings)):
                if i != j:
                    common_suffix = []
                    for obj in reversed(orderings[i]):
                        if obj not in common_suffix:
                            if obj in orderings[j]:
                                common_suffix.append(obj)
                            else:
                                break
                    else:
                        merged = True
                        orderings[i].extend(common_suffix[::-1])
                        orderings[j][-len(common_suffix):] = common_suffix
                        orderings[j][:i] = [obj for sublist in orderings[j][:i] for obj in sublist]
                        orderings[j] = orderings[j][i:]

        if not merged:
            break

    return orderings[0] if orderings else []

