def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    if not classes:
        return []

    # Sort classes by their number of direct superclasses
    classes.sort(key=lambda cls: (len(cls.__bases__), cls.__name__))

    result = [classes[0]]
    for cls in classes[1:]:
        if cls.__bases__[0] != result[-1]:
            result.append(cls)

    return result

