    errors = []
    label_key_regex = re.compile(r'^[a-zA-Z0-9._%+-]+$')

    for key, value in labels.items():
        if not isinstance(key, (str, bool)) or (isinstance(key, str) and key.startswith('$')):
            errors.append({str(key): 'Label key {} does not match the regex {}'.format(key, re.compile(r'^[a-zA-Z0-9._%+-]+$').pattern)})
            continue

        if not isinstance(value, (str, list)):
            errors.append({str(value): 'expected string or bytes-like object'})
            continue

        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    errors.append({str(item): 'expected string or bytes-like object'})

