                out_style_params.append(param)
                for key, value in param.items():
                    if key in param_indices:
                        raise ValueError(f'Duplicate parameter name: {key}')
                    param_indices[key] = i + 1
                    out_style_sql = out_style_sql.replace(f':{key}', '?')
            else:
                raise ValueError('Expected a Mapping for named parameters')
        elif self.in_style == 'ordinal':
            if isinstance(param, Sequence):
                out_style_params.append(param)
                for j, value in enumerate(param):
                    if j in param_indices:
                        raise ValueError(f'Duplicate parameter index: {j}')
                    param_indices[j] = i + 1
                    out_style_sql = out_style_sql.replace('?', f':{j}', 1)
            else:
                raise ValueError('Expected a Sequence for ordinal parameters')
        else:
            raise ValueError(f'Unsupported parameter style: {self.in_style}')

    return out_style_sql, out_style_params

