def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            # List all files in the zip file
            file_list = zip_ref.namelist()
            data_dict = {}

            for file_info in zip_ref.infolist():
                if file_info.filename.endswith('.xml'):
                    xml_basename = os.path.basename(file_info.filename)
                    # Add the file data to the dictionary under its XML basename
                    data_dict[xml_basename] = zip_ref.read(file_info.filename)

            return data_dict
    except FileNotFoundError:
        print(f"File {zip_path} not found.")
    except zipfile.BadZipFile:
        print(f"File {zip_path} is not a valid zip file.")
    except Exception as e:
        print(f"An error occurred: {str(e)}")
    return {}

