    """
    Return a pretty formatted representation of self.
    """
    indent_str = '    ' * indent
    result = indent_str + self.__class__.__name__ + '(\n'
    first = True
    for key, value in self.__dict__.items():
        if first:
            first = False
        else:
            result += ',\n'
        result += indent_str + '    ' + key + '='
        if isinstance(value, int) or isinstance(value, str) or isinstance(value, bool):
            result += str(value)
        elif isinstance(value, list):
            result += '[\n'
            result += ',\n'.join([item.pretty(indent + 2, debug) if hasattr(item, 'pretty') else repr(item) for item in value])
            result += '\n' + indent_str + '    ]'
        elif hasattr(value, 'pretty'):
            result += value.pretty(indent + 2, debug)
        else:
            result += repr(value)
    result += '\n' + indent_str + ')'
    return result if debug else result.replace('\'', '')

