    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def simplify(expr):
        if expr[0] == 'and':
            if expr[1] == expr[2]:
                return expr[1]
            if expr[1] == 'not' and expr[2] == expr[3]:
                return expr[4]
        elif expr[0] == 'or':
            if expr[1] == expr[2]:
                return expr[1]
            if expr[1] == 'not' and expr[2] == expr[3]:
                return expr[4]
        return expr

    def absorbing(val):
        if isinstance(val, list) and len(val) == 2:
            if val[0] == 'and':
                return simplify(val)
            elif val[0] == 'or':
                return simplify(val)
            elif val[0] == 'not':
