def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    import subprocess

    if not isinstance(commands, list):
        commands = [commands]

    results = []
    for command in commands:
        if verbose:
            print(f"Running command: {command} with args: {args}")

        try:
            result = subprocess.run(
                [command] + args,
                cwd=cwd,
                env=env,
                capture_output=not hide_stderr,
                text=True,
                check=True
            )
            results.append(result.stdout)
        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Command failed with error: {e}")
            if not hide_stderr:
                results.append(e.stderr)
            if not env:
                env = os.environ
                env.pop('PATH', None)
                env.pop('LD_LIBRARY_PATH', None)
                env.pop('PYTHONPATH', None)
                env.pop('TEMP', None)
                env.pop('TMP', None)
                env.pop('TMPDIR', None)

    return results

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."

    Args:
        commands (str): A single command or a list of commands.
        args (list): A list of arguments for the command(s).
        cwd (str, optional): The current working directory for the command. Defaults to None.
        verbose (bool, optional): Whether to print verbose output. Defaults to False.
        hide_stderr (bool, optional): Whether to hide the standard error output. Defaults to False.
        env (dict, optional): The environment variables to pass to the command. Defaults to None.

    Returns:
        tuple: A tuple containing the return code and the output of the command.
    """
    if verbose:
        print(f"Running command: {' '.join([commands] + args)}")

    if not isinstance(commands, list):
        commands = [commands]

    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = subprocess.STDOUT

    try:
        result = subprocess.run([commands[0], *args], cwd=cwd, stderr=stderr, env=env, text=True, check=True)
        return (result.returncode, result.stdout)
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with return code {e.returncode}: {e.output}")
        return (e.returncode, e.output)

