    """Decorator to mark a method as the handler of a VCS.

    Parameters:
        vcs (str): The version control system (e.g., 'git', 'svn')
        method (method): The method to be registered as the handler

    Returns:
        method: The original method, unchanged
    """

    if not isinstance(vcs, str):
        raise ValueError("vcs must be a string")

    if not callable(method):
        raise ValueError("method must be a callable")

    if not hasattr(method, '_vcs_handlers'):
        method._vcs_handlers = {}

    if vcs in method._vcs_handlers:
        raise ValueError(f"Handler for VCS {vcs} already registered for this method")

    method._vcs_handlers[vcs] = method

    return method

