def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    import re

    # Extract the numeric part of the version
    match = re.search(r'(\d+)$', version)
    if not match:
        raise ValueError('Invalid version format')

    current_version = int(match.group(1))
    next_version = current_version + 1

    # Reconstruct the version string
    if current_version >= 10:
        return version + '0'
    else:
        return version[:-1] + str(next_version)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.isdigit():
        return str(int(version) + 1)
    elif version[-1].isdigit():
        prefix = version[:-1]
        suffix = int(version[-1])
        return prefix + str(suffix + 1)
    else:
        raise ValueError("Invalid version format")

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    # Split the version into its numeric components
    parts = version.split('.')
    if not parts:
        return '1'

    last_part = parts[-1]
    try:
        # Try to increment the last part if it's a digit
        last_part = str(int(last_part) + 1)

        # If there are multiple parts, ensure they are zero-padded to the same length
        if len(last_part) > len(parts[-1]):
            for i in range(len(parts) - 2, -1, -1):
                parts[i] = '0'

        # Join the parts back together
        return '.'.join(parts)
    except ValueError:
        # If the last part is not a digit, append '.1' to the version
        if len(parts) > 1:
            return '.'.join(parts[:-1]) + '.1'
        else:
            return version + '.1'

