            raise FileNotFoundError(f"Inventory file for version {version_dir} does not exist")

        inventory = self._load_inventory(inventory_path)
        inventory_stamps[version_dir] = inventory['timestamp']

        for digest, files in inventory['digests'].items():
            if digest in root_inventory['digests']:
                if root_inventory['digests'][digest] != files:
                    content_digests[digest] = files
            else:
